visualData.code:
def binary_search(arr, target):
    low, high = 0, len(arr) - 1
    while low <= high:
        mid = low + (high - low) // 2
        if arr[mid] == target:
            return mid
        elif arr[mid] < target:
            low = mid + 1  # Discard mid & left
        else:
            high = mid - 1 # Discard mid & right
    return -1

